# Half-plane clipping implementation for bbox-clipped Thiessen cells in lon/lat plane
def _clip_polygon_halfplane(poly_coords, midpoint, normal, keep_positive=True, eps=1e-12):
    def side(p):
        val = (p[0] - midpoint[0]) * normal[0] + (p[1] - midpoint[1]) * normal[1]
        return val if keep_positive else -val
    if not poly_coords:
        return []
    output = []
    prev = poly_coords[-1]
    prev_side = side(prev)
    prev_inside = prev_side >= -eps
    for curr in poly_coords:
        curr_side = side(curr)
        curr_inside = curr_side >= -eps
        if curr_inside != prev_inside:
            denom = prev_side - curr_side
            if abs(denom) > eps:
                t = prev_side / denom
                output.append((prev[0] + t * (curr[0] - prev[0]), prev[1] + t * (curr[1] - prev[1])))
        if curr_inside:
            output.append(curr)
        prev, prev_side, prev_inside = curr, curr_side, curr_inside
    return output

